 void render(){root=Ui.col(this);LinearLayout header=Ui.row(this);Ui.pad(header,22,20,22,14);LinearLayout title=Ui.col(this);TextView wordmark=Ui.bold(this,"YOYO",31,Ui.C_TEXT);wordmark.setGravity(Gravity.RIGHT);title.addView(wordmark);title.addView(Ui.text(this,"قريبين، مهما كانت المسافة",12,Ui.C_MUTED));header.addView(title,new LinearLayout.LayoutParams(0,-2,1));Ui.Icon heart=Ui.icon(this,"heart",Ui.C_ACCENT,48,null);Ui.round(heart,Ui.C_SOFT,16);header.addView(heart);root.addView(header);connection=Ui.text(this,"",11,Ui.C_MUTED);Ui.pad(connection,24,0,24,8);root.addView(connection);ScrollView sc=new ScrollView(this);sc.setFillViewport(true);body=Ui.col(this);Ui.pad(body,22,6,22,18);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=Ui.row(this);Ui.pad(nav,8,8,8,8);nav.setBackgroundColor(Color.WHITE);String[] labels={"الشات","الستوري","المكالمات","الإعدادات"},icons={"chat","story","phone","settings"};for(int i=0;i<4;i++){final int pos=i;LinearLayout n=Ui.col(this);n.setGravity(Gravity.CENTER);n.addView(Ui.icon(this,icons[i],tab==i?Ui.C_ACCENT:Ui.C_MUTED,38,null));TextView navLabel=Ui.bold(this,labels[i],12,tab==i?Ui.C_ACCENT:Ui.C_MUTED);navLabel.setGravity(Gravity.CENTER);n.addView(navLabel);if(tab==i)Ui.round(n,Ui.C_SOFT,18);n.setOnClickListener(v->{tab=pos;render();});nav.addView(n,new LinearLayout.LayoutParams(0,Ui.dp(this,64),1));}root.addView(nav);Ui.page(this,root);renderContent();}
 void renderContent(){if(body==null)return;body.removeAllViews();connection.setText(RealtimeService.connected?"● متصل":"○ جاري الاتصال…");recoveryNotices();if(tab==0)chats();else if(tab==1)stories();else if(tab==2)calls();else settings();}
 void recoveryNotices(){for(java.util.Map.Entry<String,?> e:Prefs.sp(this).getAll().entrySet())if(e.getKey().startsWith("pending_key_")&&e.getValue() instanceof String&&!((String)e.getValue()).isEmpty())try{
  JSONObject p=new JSONObject((String)e.getValue());setting("مراجعة تغيير الجهاز",p.optString("name")+" استرجع الحساب أو غيّر الجهاز",()->new AlertDialog.Builder(this).setTitle("تأكيد تغيير جهاز "+p.optString("name"))
   .setMessage("تأكد من الشخص الآخر، بمكالمة أو وسيلة تعرفها، أنه استرجع حسابه فعلًا. بعد موافقتك تُستأنف الرسائل والمكالمات بالمفتاح الجديد. إذا لم يغيّر جهازه، لا توافق.")
   .setPositiveButton("تأكدت، متابعة",(d,w)->Api.job(()->{Api.acceptContactKey(this,p);Api.sync(this,false);},err->{if(err!=null)Ui.toast(this,err);renderContent();})).setNegativeButton("لاحقًا",null).show());
 }catch(Exception ignored){}}
 void section(String title,String sub){body.addView(Ui.bold(this,title,29,Ui.C_TEXT));body.addView(Ui.text(this,sub,14,Ui.C_MUTED));Ui.space(body,22);}
 void empty(String icon,String title,String sub){LinearLayout e=Ui.col(this);e.setGravity(Gravity.CENTER);Ui.pad(e,25,32,25,32);e.addView(Ui.icon(this,icon,Ui.C_ACCENT,68,null));Ui.space(e,12);TextView t=Ui.bold(this,title,21,Ui.C_TEXT);t.setGravity(Gravity.CENTER);e.addView(t);TextView s=Ui.text(this,sub,15,Ui.C_MUTED);s.setGravity(Gravity.CENTER);Ui.space(e,8);e.addView(s);body.addView(e);}
 void contactRow(JSONObject c,String sub,String icon,Runnable action){LinearLayout row=Ui.row(this);Ui.pad(row,14,16,14,16);Ui.round(row,Color.WHITE,22);ImageView av=new ImageView(this);Ui.round(av,Ui.C_SOFT,23);av.setClipToOutline(true);Avatar.into(av,c.optString("avatar"));row.addView(av,new LinearLayout.LayoutParams(Ui.dp(this,55),Ui.dp(this,55)));LinearLayout tx=Ui.col(this);Ui.pad(tx,12,0,12,0);tx.addView(Ui.bold(this,c.optString("name","YOYO"),18,Ui.C_TEXT));TextView small=Ui.text(this,sub,14,Ui.C_MUTED);small.setMaxLines(1);small.setEllipsize(android.text.TextUtils.TruncateAt.END);tx.addView(small);row.addView(tx,new LinearLayout.LayoutParams(0,-2,1));row.addView(Ui.icon(this,icon,Ui.C_ACCENT,36,null));row.setOnClickListener(v->action.run());body.addView(row);Ui.space(body,12);}
 void chats(){section("كل الحكي هون","رسائلك ولحظاتك، بمكان واحد.");JSONArray a=EventStore.contacts(this);if(a.length()==0){empty("chat","أول حكاية بتبدأ برسالة","لما الشخص الثاني ينشئ حسابه بدعوته، رح يظهر هون.");body.addView(Ui.button(this,"تحديث الأشخاص",()->Api.job(()->Api.contacts(this),e->{if(e!=null)Ui.toast(this,e);renderContent();})));}for(int i=0;i<a.length();i++){JSONObject c=a.optJSONObject(i);List<JSONObject> ms=EventStore.get(this).list(this,c.optString("id"),"chat");String pr="ابدأوا الحكي ♥";if(!ms.isEmpty()){JSONObject m=ms.get(ms.size()-1);pr=m.optString("media").equals("voice")?"رسالة صوتية":m.optString("media").equals("image")?"صورة":m.optString("text");}contactRow(c,pr,"chat",()->startActivity(new Intent(this,ChatActivity.class).putExtra("phone",c.optString("id")).putExtra("name",c.optString("name"))));}Ui.space(body,24);TextView n=Ui.text(this,"حكي قليل أو كثير… المهم مع مين.",14,Ui.C_MUTED);n.setGravity(Gravity.CENTER);body.addView(n);}
 void stories(){section("لحظاتكم","تفاصيل صغيرة، بتضل 24 ساعة.");LinearLayout add=Ui.row(this);Ui.pad(add,16,18,16,18);Ui.round(add,Ui.C_SOFT,22);add.addView(Ui.icon(this,"plus",Ui.C_ACCENT,50,null));LinearLayout t=Ui.col(this);t.addView(Ui.bold(this,"ضيف لحظة من يومك",18,Ui.C_TEXT));t.addView(Ui.text(this,"صورة أو كلمات من القلب",14,Ui.C_MUTED));add.addView(t);add.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("لحظة جديدة").setItems(new String[]{"كتابة نص","اختيار صورة"},(d,n)->{if(n==1){pick="story";picker.launch(new String[]{"image/*"});}else{EditText text=Ui.input(this,"شو حاب تشارك؟",false);new AlertDialog.Builder(this).setTitle("اكتب لحظتك").setView(text).setPositiveButton("نشر",(x,y)->Api.job(()->publishStory(text.getText().toString(),""),err->{if(err!=null)Ui.toast(this,err);renderContent();})).setNegativeButton("إلغاء",null).show();}}).show());body.addView(add);Ui.space(body,22);List<JSONObject>a=EventStore.get(this).list(this,null,"story");if(a.isEmpty())empty("story","كل يوم إله حكاية","شارك أول لحظة بتشبهك.");Collections.reverse(a);HashSet<String> ids=new HashSet<>();for(JSONObject s:a){String group=s.optString("storyId",s.optString("id"));if(!ids.add(group))continue;LinearLayout card=Ui.col(this);Ui.pad(card,20,20,20,20);Ui.round(card,Ui.C_SOFT,24);boolean mine=s.optString("from").equals(Prefs.phone(this));card.addView(Ui.bold(this,mine?"لحظتي":EventStore.contact(this,s.optString("from")).optString("name","YOYO"),15,Ui.C_ACCENT));Ui.space(card,14);if(!s.optString("data").isEmpty()){ImageView im=new ImageView(this);Avatar.into(im,s.optString("data"));card.addView(im,new LinearLayout.LayoutParams(-1,Ui.dp(this,240)));}else card.addView(Ui.bold(this,s.optString("text"),24,Ui.C_TEXT));Ui.space(card,12);if(mine){ArrayList<String>seen=new ArrayList<>();for(JSONObject x:a)if(x.optString("storyId").equals(group)&&x.optString("status").equals("read"))seen.add(EventStore.contact(this,x.optString("to")).optString("name"));card.addView(Ui.text(this,seen.isEmpty()?"لم تُشاهد بعد":"شاهدها: "+android.text.TextUtils.join("، ",seen),12,Ui.C_ACCENT));}else if(!s.optString("status").equals("read"))Api.job(()->Api.request(this,"/rest/v1/yoyo_native_events?id=eq."+s.optString("id"),"PATCH",new JSONObject().put("seen",true),true),e->{});card.addView(Ui.text(this,"تختفي خلال "+Math.max(1,(s.optLong("expires")-System.currentTimeMillis())/3600000)+" ساعة",12,Ui.C_MUTED));body.addView(card);Ui.space(body,16);}}
 void publishStory(String text,String im)throws Exception{if(text.trim().isEmpty()&&im.isEmpty())throw new Exception("اكتب نصًا أو اختر صورة");if(text.length()>1000)throw new Exception("النص طويل؛ اختصره إلى 1000 حرف");Api.contacts(this);JSONArray a=EventStore.contacts(this);if(a.length()==0)throw new Exception("بمجرد انضمام الشخص الثاني، بتقدر تشاركه ستوري");String sid=UUID.randomUUID().toString();for(int i=0;i<a.length();i++)Api.send(this,Api.base(this,a.getJSONObject(i).getString("id"),"story").put("text",text).put("data",im).put("storyId",sid));}
 void call(JSONObject c){startActivity(new Intent(this,CallActivity.class).putExtra("mode","outgoing").putExtra("phone",c.optString("id")).putExtra("name",c.optString("name")));}
 void calls(){section("صوتك أقرب","مكالمات صوتية، بتجمعكم.");JSONArray a=EventStore.contacts(this);for(int i=0;i<a.length();i++){JSONObject c=a.optJSONObject(i);contactRow(c,"مكالمة صوتية","phone",()->call(c));}if(a.length()==0)empty("phone","ناقصنا الصوت الثاني","رح تقدر تتصل بمجرد انضمام الحساب الثاني.");Ui.space(body,10);body.addView(Ui.bold(this,"سجل المكالمات",18,Ui.C_TEXT));List<JSONObject>logs=EventStore.get(this).list(this,null,"call_log");Collections.reverse(logs);for(JSONObject o:logs){JSONObject c=EventStore.contact(this,o.optString("to"));contactRow(c,o.optString("text")+" · "+new java.text.SimpleDateFormat("dd/MM HH:mm",Locale.getDefault()).format(new Date(o.optLong("ts"))),"phone",()->call(c));}if(logs.isEmpty()){Ui.space(body,15);body.addView(Ui.text(this,"مكالماتكم رح تظهر هون.",15,Ui.C_MUTED));}}
 void setting(String label,String sub,Runnable action){LinearLayout r=Ui.col(this);Ui.pad(r,16,17,16,17);Ui.round(r,Color.WHITE,18);r.addView(Ui.bold(this,label,17,Ui.C_TEXT));if(!sub.isEmpty())r.addView(Ui.text(this,sub,13,Ui.C_MUTED));r.setOnClickListener(v->action.run());body.addView(r);Ui.space(body,10);}
 void settings(){section("على ذوقك","تفاصيلك الصغيرة، بطريقتك.");if(Prefs.get(this,"slot").equals("1"))setting("دعوة شخص","أنت صاحب التطبيق · لحد 6 حسابات",this::invitePerson);JSONObject me=new JSONObject();try{me.put("name",Prefs.name(this)).put("avatar",Prefs.avatar(this));}catch(Exception e){}contactRow(me,"اسم الدخول: "+Prefs.get(this,"login_name"),"settings",()->{EditText t=Ui.input(this,"اسمك",false);t.setText(Prefs.name(this));new AlertDialog.Builder(this).setTitle("اسمك الظاهر").setView(t).setPositiveButton("حفظ",(d,w)->Api.job(()->{String n=t.getText().toString().trim();if(n.isEmpty()||n.length()>60)throw new Exception("اكتب اسمًا من 1 إلى 60 حرفًا");Api.profile(this,n,Prefs.avatar(this));},e->{if(e!=null)Ui.toast(this,e);render();})).setNegativeButton("إلغاء",null).show();});setting("الصورة الشخصية","إضافة صورة أو إزالتها",()->new AlertDialog.Builder(this).setItems(new String[]{"اختيار صورة","إزالة الصورة"},(d,n)->{if(n==0){pick="avatar";picker.launch(new String[]{"image/*"});}else Api.job(()->Api.profile(this,Prefs.name(this),""),e->{if(e!=null)Ui.toast(this,e);render();});}).show());setting("الإشعارات والرنين","الصوت والاهتزاز وظهور الرسائل",()->startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName())));setting("العمل بالخلفية","إعدادات البطارية على هاتفك",()->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()))));if(Build.VERSION.SDK_INT>=34)setting("شاشة المكالمة الواردة","السماح بعرض الاتصال على الشاشة",()->startActivity(new Intent(Settings.ACTION_MANAGE_APP_USE_FULL_SCREEN_INTENT,Uri.parse("package:"+getPackageName()))));setting("تغيير كلمة السر","كلمة قوية، لمساحتكم الخاصة",()->{EditText p=Ui.input(this,"كلمة السر الجديدة",true);new AlertDialog.Builder(this).setTitle("تغيير كلمة السر").setView(p).setPositiveButton("حفظ",(d,w)->Api.job(()->{if(p.length()<8)throw new Exception("8 أحرف أو أرقام على الأقل");Api.request(this,"/auth/v1/user","PUT",new JSONObject().put("password",p.getText().toString()),true);},e->Ui.toast(this,e==null?"تم تغيير كلمة السر":e))).setNegativeButton("إلغاء",null).show();});setting("عن يويو","نسخة أولى للتجربة · Android",()->new AlertDialog.Builder(this).setTitle("YOYO · "+BuildConfig.VERSION_NAME).setMessage("شات وصور وفويس وستوري ومكالمات صوتية.\n\nالاتصال بالخلفية يعتمد على استمرار إشعار يويو وإعدادات البطارية. بعض الشبكات تحتاج TURN وهي غير مربوطة بعد.\n\nبعد حذف التطبيق يمكن استرجاع الحساب بكلمة المرور؛ الرسائل القديمة تحتاج مفتاحها القديم. نسخة "+BuildConfig.VERSION_NAME+" — YOYO الجديد مع تحديثات تلقائية محسّنة.").setPositiveButton("تمام",null).show());setting("تسجيل الخروج","",()->new AlertDialog.Builder(this).setTitle("تسجيل الخروج؟").setMessage("ستتوقف الإشعارات حتى تدخل مجددًا.").setPositiveButton("خروج",(d,w)->{stopService(new Intent(this,RealtimeService.class));Api.job(()->Api.request(this,"/auth/v1/logout","POST",new JSONObject(),true),e->{Prefs.put(this,"refresh","");Prefs.put(this,"token","");welcome();});}).setNegativeButton("إلغاء",null).show());Ui.space(body,22);TextView foot=Ui.bold(this,"YOYO  ♥  إلكم وبس",15,Ui.C_MUTED);foot.setGravity(Gravity.CENTER);body.addView(foot);}
 void invitePerson(){String saved=Prefs.get(this,"last_invitation");if(!saved.isEmpty()){showInvitation(saved);return;}createInvitation();}
 void createInvitation(){new AlertDialog.Builder(this).setTitle("إنشاء دعوة").setMessage("الرمز للشخص التالي ويُستخدم مرة واحدة. إنشاء رمز جديد يلغي الرمز السابق غير المستخدم.").setPositiveButton("إنشاء دعوة",(dialog,which)->{
  final JSONObject[] result={null};Api.job(()->result[0]=new JSONObject(Api.request(this,"/functions/v1/yoyo-native-invite","POST",new JSONObject(),true)),err->{
   if(isFinishing()||isDestroyed())return;if(err!=null){Ui.toast(this,err);return;}
   String code=Invitation.extract(result[0].optString("invite"));if(code.isEmpty()){Ui.toast(this,"لم يصل رمز صالح. حاول إنشاء الدعوة مجددًا.");return;}Prefs.put(this,"last_invitation",code);showInvitation(code);
  });}).setNegativeButton("إلغاء",null).show();}
 void showInvitation(String code){
  LinearLayout box=Ui.col(this);Ui.pad(box,24,12,24,16);box.addView(Ui.text(this,"رمز الدعوة — يُدخل مرة واحدة",16,Ui.C_MUTED));
  TextView value=Ui.bold(this,code,28,Ui.C_ACCENT);value.setLayoutDirection(View.LAYOUT_DIRECTION_LTR);value.setGravity(Gravity.CENTER);value.setTextIsSelectable(true);Ui.pad(value,8,18,8,18);box.addView(value);
  TextView copy=Ui.button(this,"نسخ الرمز فقط",()->{((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("رمز الدعوة",code));Ui.toast(this,"تم نسخ الرمز فقط؛ أرسله للشخص الثاني");});box.addView(copy,new LinearLayout.LayoutParams(-1,Ui.dp(this,54)));Ui.space(box,12);
  TextView share=Ui.button(this,"مشاركة الرابط والرمز",()->startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,Invitation.message(code)),"مشاركة الدعوة")));box.addView(share,new LinearLayout.LayoutParams(-1,Ui.dp(this,54)));Ui.space(box,12);
  box.addView(Ui.text(this,"إذا استخدم الشخص السابق هذا الرمز، أنشئ دعوة جديدة للشخص التالي.",13,Ui.C_MUTED));
  new AlertDialog.Builder(this).setTitle("دعوتك جاهزة").setView(box).setPositiveButton("إغلاق",null).setNeutralButton("إنشاء رمز جديد",(d,w)->createInvitation()).show();
 }

 protected void onResume(){super.onResume();ContextCompat.registerReceiver(this,events,new IntentFilter(RealtimeService.ACTION_EVENT),ContextCompat.RECEIVER_NOT_EXPORTED);if(Prefs.hasProfile(this)){RealtimeService.start(this);Api.job(()->Api.sync(this,false),e->{if(e==null)renderContent();});}}protected void onPause(){unregisterReceiver(events);super.onPause();}
